DB::transaction(function () use (&$claimed, &$skip, &$domainEvent): void {
    $domainEvent = DomainEvent::query()->lockForUpdate()->find($this->domainEventId);
    if ($domainEvent->dispatched_at !== null) {
        $skip = true;
        return;
    }
    $domainEvent->forceFill(['dispatched_at' => now(), 'attempts' => ((int) $domainEvent->attempts) + 1])->save();
    $claimed = true;
});

